package vn.contractgovernance.api.obligation;

import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import static vn.contractgovernance.api.obligation.DutyEvidence.id;

@Service
public class ObligationService {
 private final org.springframework.beans.factory.ObjectProvider<ServiceEndProof> serviceProof;private final DutyEvidence e;private final LifecycleObligations lifecycle;private final CommandExecutor commands;private final ContractRegistry schemas;private final AuditService audit;private final ListQueries lists;
 public ObligationService(org.springframework.beans.factory.ObjectProvider<ServiceEndProof> serviceProof,DutyEvidence e,LifecycleObligations lifecycle,CommandExecutor commands,ContractRegistry schemas,AuditService audit,ListQueries lists){this.serviceProof=serviceProof;this.e=e;this.lifecycle=lifecycle;this.commands=commands;this.schemas=schemas;this.audit=audit;this.lists=lists;}
 public EntityStore.Entity require(UUID id,Actor a){return e.require("Obligation",id,a);}
 public JsonNode get(UUID id,Actor a){return project(require(id,a),e.current(a));}
 public JsonNode list(Map<String,String> q,Actor a){a=e.current(a);var args=new ArrayList<Object>();String where=e.scope(a,args);if(q.containsKey("type")){where+=" and e.body->>'type'=?";args.add(q.get("type"));}if(q.containsKey("dueBefore")){where+=" and (e.body->>'currentDueAt')::timestamptz<?";args.add(Timestamp.from(Instant.parse(q.get("dueBefore"))));}if(q.containsKey("everBreached")){where+=" and "+(q.get("everBreached").equals("true")?"":"not ")+"exists(select 1 from cg_lifecycle_obligation_breach b where b.obligation_id=e.id)";}var filtered=new HashMap<>(q);filtered.remove("dueBefore");final Actor actor=a;return lists.page("Obligation",a,filtered,false,where,args,b->project(entity(b),actor));}
 private EntityStore.Entity entity(JsonNode b){return new EntityStore.Entity("Obligation",id(b,"id"),id(b,"branchId"),b.path("version").asInt(),b);}
 private void authorize(UUID id,String action,Actor a){var duty=require(id,a);if(Set.of("SUBMIT_EVIDENCE","REQUEST_EXTENSION","REQUEST_WAIVER").contains(action))e.maker(duty,a);else e.independent(duty,a,action.startsWith("DECIDE_")?"MANAGER":"CHECKER");}
 public ApiResult command(UUID id,JsonNode r,String tag,String key,Actor a){String action=r.path("action").asString();authorize(id,action,a);ETags.require(tag);return commands.execute(a,key,"POST","/api/v1/obligations/"+id+"/commands",r,tag,()->authorize(id,action,a),()->{var duty=e.lock("Obligation",id);authorize(id,action,a);ETags.check(tag,duty.version());if(terminal(duty.body()))throw ApiException.of("STATE_CONFLICT","Nghĩa vụ đã kết thúc.");lifecycle.synchronizeBreach(duty);duty=e.store.require("Obligation",id);var b=(ObjectNode)duty.body().deepCopy();
 switch(action){
 case "SUBMIT_EVIDENCE"->{state(b,"OPEN","RETURNED");if(b.path("type").asString().equals("NOTICE_ACK"))throw ApiException.of("NOTICE_NOT_READY","ACK phải đi qua candidate và xác minh Notice độc lập.");var ids=e.ids(r.path("evidenceFileIds"));var all=new TreeSet<>(ids);for(var receipt:r.path("externalConfirmations")){e.nonfuture(receipt.path("observedAt"));all.addAll(e.ids(receipt.path("fileIds")));}var manifest=e.manifest(duty,all,a,true);var contributors=e.uploaders(manifest);contributors.add(a.id());e.contribute(duty,b,contributors);var source=e.json.object();source.set("request",r);source.set("manifest",manifest);source.set("contributors",b.path("contributorIds"));e.event(duty,"SUBMISSION",source,a);b.put("state","EVIDENCE_SUBMITTED").put("evidenceSummary",r.path("summary").asString()).put("closureOutcome",r.path("closureOutcome").asString());b.set("evidenceFileIds",r.path("evidenceFileIds"));b.set("externalConfirmations",r.path("externalConfirmations"));}
 case "APPROVE"->{state(b,"EVIDENCE_SUBMITTED");var submitted=e.latest(duty,"SUBMISSION");verifyManifest(duty,submitted.path("manifest"),a);checkClosure(duty,submitted.path("request"),a);e.event(duty,"ACCEPT_SUBMISSION",assessment(r,submitted),a);b.put("state","CLOSED");}
 case "RETURN"->{state(b,"EVIDENCE_SUBMITTED");var submitted=e.latest(duty,"SUBMISSION");e.event(duty,"RETURN_SUBMISSION",assessment(r,submitted),a);b.put("state","RETURNED");}
 case "REQUEST_EXTENSION","REQUEST_WAIVER"->{waivable(b);String field=action.equals("REQUEST_EXTENSION")?"extensionRequest":"waiverRequest";if(b.hasNonNull(field)&&b.path(field).path("state").asString().equals("PENDING"))throw ApiException.of("STATE_CONFLICT","Yêu cầu trước còn chờ.");if(field.equals("extensionRequest")){var due=Instant.parse(r.path("requestedDueAt").asString());if(!due.isAfter(Instant.parse(b.path("currentDueAt").asString()))||!due.isAfter(e.clock.instant()))throw ApiException.validation("/requestedDueAt","Hạn mới phải ở tương lai và sau hạn hiện hành.");}var manifest=e.manifest(duty,e.ids(r.path("evidenceFileIds")),a,true);var contributors=e.uploaders(manifest);contributors.add(a.id());e.contribute(duty,b,contributors);var request=e.json.object().put("id",UUID.randomUUID().toString()).put("requesterId",a.id().toString()).put("reason",r.path("reason").asString()).put("state","PENDING").putNull("decisionBy").putNull("decidedAt");request.set("contributors",e.json.value(contributors.stream().map(UUID::toString).toList()));request.set("evidenceFileIds",r.path("evidenceFileIds"));if(field.equals("extensionRequest"))request.set("requestedDueAt",r.path("requestedDueAt"));else request.putNull("requestedDueAt");b.set(field,request);var frozen=e.json.object();frozen.set("request",request);frozen.set("manifest",manifest);e.event(duty,field+"_SOURCE",frozen,a);}
 case "DECIDE_EXTENSION","DECIDE_WAIVER"->{waivable(b);String field=action.equals("DECIDE_EXTENSION")?"extensionRequest":"waiverRequest";var request=(ObjectNode)b.path(field).deepCopy();if(!request.path("id").equals(r.path("requestId"))||!request.path("state").asString().equals("PENDING"))throw ApiException.of("STATE_CONFLICT","Không có đúng yêu cầu đang chờ.");if(request.path("requesterId").asString().equals(a.id().toString()))throw ApiException.of("SOD_VIOLATION","Không tự quyết định yêu cầu.");var frozen=e.latest(duty,field+"_SOURCE");verifyManifest(duty,frozen.path("manifest"),a);var bilateral=e.manifest(duty,e.ids(r.path("bilateralAcceptanceFileIds")),a,true);if(e.uploaders(bilateral).contains(a.id()))throw ApiException.of("SOD_VIOLATION","Manager không tự cung cấp bilateral proof.");e.contribute(duty,b,e.uploaders(bilateral));boolean approve=r.path("decision").asString().equals("APPROVE");if(approve&&b.path("basisType").asString().equals("CONTRACTUAL")&&bilateral.isEmpty())throw ApiException.of("READINESS_BLOCKED","Cần bằng chứng chấp nhận song phương được manager độc lập xét.");request.put("state",approve?"APPROVED":"REJECTED").put("decisionBy",a.id().toString()).put("decidedAt",e.now());b.set(field,request);var decision=assessment(r,frozen);decision.set("bilateralManifest",bilateral);e.event(duty,action,decision,a);if(approve){if(field.equals("waiverRequest"))b.put("state","CANCELLED").put("closureOutcome","WAIVED");else{Instant due=Instant.parse(request.path("requestedDueAt").asString());if(!due.isAfter(e.clock.instant())||!due.isAfter(Instant.parse(b.path("currentDueAt").asString())))throw ApiException.validation("/requestedDueAt","Hạn yêu cầu không còn là gia hạn tương lai.");if(b.path("deadlineHistory").size()>=100)throw ApiException.of("STATE_CONFLICT","Lịch sử hạn đã đủ 100.");int revision=b.path("dueRevision").asInt()+1;var history=e.json.object().put("number",revision).put("dueAt",JsonSupport.timestamp(due)).put("effectiveAt",e.now()).put("decisionBy",a.id().toString()).put("basis",r.path("basis").asString()).putNull("breachedAt");e.store.jdbc().update("insert into cg_obligation_due(obligation_id,number,due_at,effective_at,decision_by,basis) values(?,?,?,?,?,?)",id,revision,Timestamp.from(due),Timestamp.from(e.clock.instant()),a.id(),r.path("basis").asString());b.put("dueRevision",revision).put("currentDueAt",JsonSupport.timestamp(due));b.withArray("deadlineHistory").add(history);}}}
 case "SUPERSEDE","CANCEL_INAPPLICABLE"->{ending(duty,r,a);b.put("state","CANCELLED").putNull("closureOutcome");if(r.hasNonNull("replacementId"))b.set("supersededById",r.path("replacementId"));}
 default->throw ApiException.validation("/action","Command không hỗ trợ.");}
 return ApiResult.ok(project(save(duty,b,a,action,r.path("reason").asString()),a));});}
 private ObjectNode assessment(JsonNode request,JsonNode source){var out=e.json.object();out.set("request",request);out.put("sourceHash",e.json.hash(source));return out;}
 private void verifyManifest(EntityStore.Entity d,JsonNode m,Actor a){var ids=new TreeSet<UUID>();for(var f:m)ids.add(id(f,"fileId"));if(!e.manifest(d,ids,a,false).equals(m))throw ApiException.of("STORAGE_INTEGRITY","Bằng chứng khác bản đã nộp.");}
 private void waivable(JsonNode b){if(b.path("basisType").asString().equals("STATUTORY_EXTERNAL"))throw ApiException.of("NONWAIVABLE_DUTY","Hạn bên ngoài không được ứng dụng gia hạn/miễn.");}
 private void ending(EntityStore.Entity d,JsonNode r,Actor a){String type=d.body().path("type").asString();if(!type.equals("TERM_REVIEW")&&!type.equals("NOTICE_ACK"))throw ApiException.of("STATE_CONFLICT","Nguồn này không được hủy tính áp dụng.");if(type.equals("TERM_REVIEW")){var c=e.store.require("Contract",id(d.body(),"contractId"));if(c.body().path("state").asString().equals("ACTIVE")&&c.body().path("currentVersion").path("id").equals(d.body().path("sourceId")))throw ApiException.of("STATE_CONFLICT","TERM_REVIEW vẫn thuộc phiên bản hiện hành.");}else{var n=e.store.require("Notice",id(d.body(),"sourceId"));if(!n.body().path("state").asString().equals("CANCELLED")&&!n.body().path("superseded").asBoolean())throw ApiException.of("NOTICE_NOT_READY","Notice vẫn áp dụng.");}if(r.hasNonNull("replacementId")){var replacement=require(id(r,"replacementId"),a);if(replacement.id().equals(d.id())||!replacement.body().path("contractId").equals(d.body().path("contractId"))||!replacement.body().path("type").equals(d.body().path("type"))||terminal(replacement.body()))throw ApiException.validation("/replacementId","Cần successor thực cùng hợp đồng/type.");}var m=e.manifest(d,e.ids(r.path("evidenceFileIds")),a,true);if(e.uploaders(m).contains(a.id()))throw ApiException.of("SOD_VIOLATION","Người kết luận không tự cung cấp bằng chứng.");var event=e.json.object();event.set("request",r);event.set("manifest",m);e.event(d,"ENDING",event,a);}
 private void checkClosure(EntityStore.Entity d,JsonNode submission,Actor a){String type=d.body().path("type").asString();if(type.equals("TERM_REVIEW")&&!Set.of("RENEW","DECLINE","NEW_AGREEMENT").contains(submission.path("closureOutcome").asString()))throw ApiException.validation("/closureOutcome","TERM_REVIEW cần intent RENEW/DECLINE/NEW_AGREEMENT, không tự áp dụng renewal.");if(type.equals("CLOSEOUT")){var contract=id(d.body(),"contractId");if(e.store.jdbc().queryForObject("select count(*) from cg_entity where entity_type='Incident' and body->>'contractId'=? and body->>'state'<>'CLOSED'",Long.class,contract.toString())>0||e.store.jdbc().queryForObject("select count(*) from cg_entity where entity_type='Obligation' and body->>'contractId'=? and id<>? and body->>'state' not in ('CLOSED','CANCELLED')",Long.class,contract.toString(),d.id())>0)throw ApiException.of("READINESS_BLOCKED","Còn Incident/nghĩa vụ chưa kết thúc.");if(submission.path("externalConfirmations").isEmpty())throw ApiException.of("READINESS_BLOCKED","Cần independent assessment external settlement/fee/complaint hoặc not-applicable proof.");if(!verifiedServiceEnded(contract))throw ApiException.of("READINESS_BLOCKED","Chưa có nguồn xác nhận dịch vụ dừng hoặc never-started độc lập.");}if(type.equals("REMEDIATION")&&!submission.path("closureOutcome").asString().equals("FULFILLED"))throw ApiException.validation("/closureOutcome","Remediation cần FULFILLED.");if(type.equals("NOTICE_ACK"))throw ApiException.of("NOTICE_NOT_READY","Chỉ Notice VERIFY_ACK đóng nghĩa vụ ACK.");}
 /** Reads real confirmed controls; observed state by itself is never proof. Control will preserve immutable confirmation binding. */
 public boolean verifiedServiceEnded(UUID contract){var proof=serviceProof.getIfAvailable();return proof!=null&&proof.verifiedEnded(contract);}
 public EntityStore.Entity save(EntityStore.Entity d,ObjectNode b,Actor a,String action,String reason){b.put("updatedAt",e.now());var updated=e.store.update(d,b);schemas.validateSchema("Obligation",updated.body());audit.record(a,action,updated,reason);return updated;}
 public JsonNode project(EntityStore.Entity duty,Actor a){var b=(ObjectNode)duty.body().deepCopy();var unresolved=e.store.jdbc().query("select id from cg_entity where entity_type='Incident' and body->>'contractId'=? and body->>'state'<>'CLOSED' order by id limit 101",(rs,n)->rs.getObject(1,UUID.class),b.path("contractId").asString());if(unresolved.size()>100)throw ApiException.of("STATE_CONFLICT","Vượt 100 unresolved Incident schema limit.");b.set("unresolvedIncidentIds",e.json.value(unresolved.stream().map(UUID::toString).toList()));var actions=e.json.array();var blocked=e.json.array();if(!terminal(b))for(var action:List.of("SUBMIT_EVIDENCE","APPROVE","RETURN","REQUEST_EXTENSION","DECIDE_EXTENSION","REQUEST_WAIVER","DECIDE_WAIVER","SUPERSEDE","CANCEL_INAPPLICABLE")){boolean relevant=switch(action){case "SUBMIT_EVIDENCE"->Set.of("OPEN","RETURNED").contains(b.path("state").asString())&&!b.path("type").asString().equals("NOTICE_ACK");case "APPROVE","RETURN"->b.path("state").asString().equals("EVIDENCE_SUBMITTED");case "DECIDE_EXTENSION"->b.hasNonNull("extensionRequest")&&b.path("extensionRequest").path("state").asString().equals("PENDING");case "DECIDE_WAIVER"->b.hasNonNull("waiverRequest")&&b.path("waiverRequest").path("state").asString().equals("PENDING");case "SUPERSEDE","CANCEL_INAPPLICABLE"->Set.of("TERM_REVIEW","NOTICE_ACK").contains(b.path("type").asString());default->true;};if(!relevant)continue;try{authorize(duty.id(),action,a);if(action.contains("EXTENSION")||action.contains("WAIVER"))waivable(b);if(action.equals("APPROVE"))checkClosure(duty,e.latest(duty,"SUBMISSION").path("request"),a);actions.add(action);}catch(ApiException ex){if(!a.hasRole("AUDITOR"))blocked.add(e.json.object().put("action",action).put("code",ex.code()).put("reason",ex.getMessage()));}}if(e.redacted(a)){b.put("basisText","[REDACTED]");if(b.hasNonNull("evidenceSummary"))b.put("evidenceSummary","[REDACTED]");for(String field:List.of("extensionRequest","waiverRequest"))if(b.hasNonNull(field))((ObjectNode)b.path(field)).put("reason","[REDACTED]");for(var h:b.path("deadlineHistory"))((ObjectNode)h).put("basis","[REDACTED]");for(var c:b.path("externalConfirmations"))((ObjectNode)c).put("basis","[REDACTED]");}b.set("allowedActions",actions);b.set("blockedActions",blocked);return b;}
 private boolean terminal(JsonNode b){return Set.of("CLOSED","CANCELLED").contains(b.path("state").asString());}
 private void state(JsonNode b,String...states){if(!Set.of(states).contains(b.path("state").asString()))throw ApiException.of("STATE_CONFLICT","Nghĩa vụ không ở trạng thái phù hợp.");}
}
